update libread_internal.issue139_batch2_legend_20261115 t
  set body_before = e.body
from public.episodes e
where e.id = t.episode_id and e.series_id = t.series_id and e.episode_number = 1;

update libread_internal.issue139_batch2_legend_drop_20261115 d
  set dropped_row = (select to_jsonb(e) from public.episodes e
                     where e.id = d.dropped_episode_id and e.series_id = d.series_id and e.episode_number = 1),
      episodes_before = (select jsonb_agg(jsonb_build_object('id', e.id, 'episode_number', e.episode_number,
                                                              'title', e.title, 'body_md5', md5(e.body))
                                          order by e.episode_number)
                         from public.episodes e where e.series_id = d.series_id);

do $$ begin
  if (select count(*) from libread_internal.issue139_batch2_legend_20261115 where body_before is not null) <> 40
     or (select count(*) from libread_internal.issue139_batch2_legend_drop_20261115 where dropped_row is not null) <> 4 then
    raise exception 'ISSUE139_BATCH2_LEGEND_SCOPE';
  end if;
  if exists (select 1 from libread_internal.issue139_batch2_legend_20261115
             where md5(left(body_before, prefix_chars)) <> prefix_md5
                or position('【テキスト中に現れる記号について】' in left(body_before, prefix_chars)) = 0
                or position('【テキスト中に現れる記号について】' in substr(body_before, prefix_chars + 1)) > 0) then
    raise exception 'ISSUE139_BATCH2_LEGEND_PREFIX_DRIFT';
  end if;
  if exists (select 1 from libread_internal.issue139_batch2_legend_drop_20261115 d
             where position('【テキスト中に現れる記号について】' in d.dropped_row->>'body') = 0
                or jsonb_array_length(d.episodes_before) < 2
                or exists (select 1 from public.episodes e
                           where e.series_id = d.series_id and e.title !~ ' — Part [0-9]+$')) then
    raise exception 'ISSUE139_BATCH2_LEGEND_DROP_SHAPE';
  end if;
  if exists (
    select 1 from (
      select episode_id from libread_internal.issue139_batch2_legend_20261115
      union all select dropped_episode_id from libread_internal.issue139_batch2_legend_drop_20261115
    ) t
    where exists (select 1 from public.episode_translations x where x.episode_id = t.episode_id)
       or exists (select 1 from public.episode_human_translations x where x.episode_id = t.episode_id)
       or exists (select 1 from public.recordings x where x.episode_id = t.episode_id)
       or exists (select 1 from public.user_episode_comments x where x.episode_id = t.episode_id)
       or exists (select 1 from public.public_episode_translation_unlocks x where x.episode_id = t.episode_id)
  ) then
    raise exception 'ISSUE139_BATCH2_LEGEND_DEPENDENT_ROWS';
  end if;
  if exists (select 1 from libread_internal.issue139_batch2_legend_drop_20261115 d
             join public.series_view_events x on x.episode_id = d.dropped_episode_id) then
    raise exception 'ISSUE139_BATCH2_LEGEND_DROP_HAS_VIEWS';
  end if;
end $$;

do $$ declare n integer; begin
  update public.episodes e
    set body = substr(t.body_before, t.prefix_chars + 1)
  from libread_internal.issue139_batch2_legend_20261115 t
  where e.id = t.episode_id and e.body = t.body_before;
  get diagnostics n = row_count;
  if n <> 40 then raise exception 'ISSUE139_BATCH2_LEGEND_ROWCOUNT %', n; end if;
  update libread_internal.issue139_batch2_legend_20261115 t
    set body_after_md5 = md5(e.body)
  from public.episodes e where e.id = t.episode_id;

  delete from public.episodes e using libread_internal.issue139_batch2_legend_drop_20261115 d
   where e.id = d.dropped_episode_id and e.episode_number = 1;
  get diagnostics n = row_count;
  if n <> 4 then raise exception 'ISSUE139_BATCH2_LEGEND_DROP_ROWCOUNT %', n; end if;
  update public.episodes e set episode_number = e.episode_number + 100000
    from libread_internal.issue139_batch2_legend_drop_20261115 d where e.series_id = d.series_id;
  update public.episodes e
    set episode_number = e.episode_number - 100001,
        title = regexp_replace(e.title, ' — Part [0-9]+$', ' — Part ' || (e.episode_number - 100001)::text)
    from libread_internal.issue139_batch2_legend_drop_20261115 d where e.series_id = d.series_id;
  update public.episodes e
    set body = d.carry || E'\n\n' || e.body
    from libread_internal.issue139_batch2_legend_drop_20261115 d
   where e.series_id = d.series_id and e.episode_number = 1 and d.carry <> '';
  if exists (select 1 from libread_internal.issue139_batch2_legend_drop_20261115 d
             where (select min(e.episode_number) from public.episodes e where e.series_id = d.series_id) <> 1
                or (select max(e.episode_number) from public.episodes e where e.series_id = d.series_id)
                   <> jsonb_array_length(d.episodes_before) - 1
                or (select count(*) from public.episodes e where e.series_id = d.series_id)
                   <> jsonb_array_length(d.episodes_before) - 1) then
    raise exception 'ISSUE139_BATCH2_LEGEND_DROP_RENUMBER';
  end if;
  if exists (select 1 from public.episodes e
             where e.series_id in (select series_id from libread_internal.issue139_batch2_legend_20261115
                                   union all select series_id from libread_internal.issue139_batch2_legend_drop_20261115)
               and position('【テキスト中に現れる記号について】' in e.body) > 0) then
    raise exception 'ISSUE139_BATCH2_LEGEND_STILL_PRESENT';
  end if;
end $$;
